using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.OpenApi.Models;

namespace {{ SolutionName }}.Api.Extensions;

public static class SwaggerServiceExtensions
{
    public static IServiceCollection AddProjectSwagger(this IServiceCollection services, string title)
    {
        services.AddEndpointsApiExplorer();
        services.AddSwaggerGen(options =>
        {
            options.SwaggerDoc("v1", new OpenApiInfo
            {
                Title = title,
                Version = "v1"
            });

            var xmlDocumentation = Path.Combine(AppContext.BaseDirectory, $"{typeof(SwaggerServiceExtensions).Assembly.GetName().Name}.xml");
            if (File.Exists(xmlDocumentation))
            {
                options.IncludeXmlComments(xmlDocumentation);
            }
        });

        return services;
    }

    public static WebApplication UseProjectSwagger(this WebApplication app)
    {
        app.UseSwagger();
        app.UseSwaggerUI();
        return app;
    }
}

